# SniperClip V5.48e - application Windows + SQLite
# Gestionnaire de copier/coller léger pour Windows
# Double-clic sur une case : modifier
# Clic gauche : copier le contenu dans le presse-papiers
# Clic droit : modifier le contenu
# Ctrl+Alt+V : masquer la fenêtre
# Echap : masquer la fenêtre

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

# Contrôle natif de la visibilité de la fenêtre sans modifier son état WinForms.
# Cela permet de masquer/afficher une fenêtre lancée avec ShowDialog() sans
# interrompre sa boucle modale ni la réduire dans la barre des tâches.
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class SniperClipNativeWindow {
    [DllImport("user32.dll")]
    public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

    [DllImport("user32.dll")]
    public static extern bool SetForegroundWindow(IntPtr hWnd);
}
"@

# Instance unique : un second lancement réactive l'instance existante puis se termine.
Add-Type @"
using System;
using System.Threading;
using System.Runtime.InteropServices;
public static class SniperClipInstanceGuard {
    public static Mutex Mutex;
    [DllImport("user32.dll", CharSet=CharSet.Unicode)]
    public static extern IntPtr FindWindow(string lpClassName, string lpWindowName);
    [DllImport("user32.dll")]
    public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
    [DllImport("user32.dll")]
    public static extern bool SetForegroundWindow(IntPtr hWnd);
}
"@
$script:singleInstanceMutex = New-Object System.Threading.Mutex($false, "Local\SniperClip_SingleInstance")
try {
    if(-not $script:singleInstanceMutex.WaitOne(0)) {
        $existing=[SniperClipInstanceGuard]::FindWindow($null,"SniperClip")
        if($existing -ne [IntPtr]::Zero){ [SniperClipInstanceGuard]::ShowWindow($existing,9) | Out-Null; [SniperClipInstanceGuard]::SetForegroundWindow($existing) | Out-Null }
        [System.Environment]::Exit(0)
    }
} catch { [System.Environment]::Exit(0) }
$AppName = "SniperClip"
$DataDir = Join-Path $env:APPDATA $AppName
$DatabaseFile = Join-Path $DataDir "SniperClip.db"
$script:LogDir = Join-Path $DataDir "Logs"
$script:LogFile = Join-Path $script:LogDir "SniperClip.log"
New-Item -ItemType Directory -Force -Path $script:LogDir | Out-Null
function Write-SniperClipLog([string]$message,[string]$level="INFO") {
    try { Add-Content -LiteralPath $script:LogFile -Value ((Get-Date).ToString("yyyy-MM-dd HH:mm:ss")+" [$level] "+$message) -Encoding UTF8 } catch {}
}
$script:isInitializing = $true
$script:restartRequested = $false
$script:skipFinalSave = $false
$script:Language = "fr"
$script:LangMap = @{}
$script:LangMapJsonB64 = ""
try {
    $jsonText = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($script:LangMapJsonB64))
    $jsonObj = $jsonText | ConvertFrom-Json
    foreach($langProp in $jsonObj.PSObject.Properties){
        $h = @{}
        foreach($entry in $langProp.Value.PSObject.Properties){ $h[$entry.Name] = [string]$entry.Value }
        $script:LangMap[$langProp.Name] = $h
    }

    # Alias de migration de nom : les traductions historiques utilisent
    # encore « ClipGrid ». On crée automatiquement les mêmes entrées pour
    # « SniperClip », sans modifier les traductions déjà existantes.
    # Alias de migration de nom : les traductions historiques utilisent
    # encore « ClipGrid ». On crée les mêmes entrées pour « SniperClip ».
    # La liste des clés est copiée dans un tableau avant modification afin
    # d'éviter toute modification de collection pendant son énumération.
    foreach($langName in @("fr","en","es","de","pl","ja","it")) {
        if(-not $script:LangMap.ContainsKey($langName)){ $script:LangMap[$langName]=@{} }
        $h=$script:LangMap[$langName]
        $keysSnapshot=@($h.Keys)
        foreach($key in $keysSnapshot){
            if([string]$key -like '*ClipGrid*'){
                $newKey=([string]$key).Replace('ClipGrid','SniperClip')
                $newValue=([string]$h[$key]).Replace('ClipGrid','SniperClip')
                if(-not $h.ContainsKey($newKey)){
                    $h[$newKey]=$newValue
                }
            }
        }
    }
}catch { $script:LangMap=@{} }

function T([string]$text){
    if($script:LangMap.ContainsKey($script:Language) -and $script:LangMap[$script:Language].ContainsKey($text)){
        return $script:LangMap[$script:Language][$text]
    }
    return $text
}

function Show-LocalizedConfirm([System.Windows.Forms.IWin32Window]$owner,[string]$message){
    $yesText = @{fr="Oui"; en="Yes"; es="Sí"; de="Ja"; pl="Tak"; ja="はい"; it="Sì"}[$script:Language]
    $noText  = @{fr="Non"; en="No"; es="No"; de="Nein"; pl="Nie"; ja="いいえ"; it="No"}[$script:Language]
    if([string]::IsNullOrEmpty($yesText)){ $yesText="Yes" }
    if([string]::IsNullOrEmpty($noText)){ $noText="No" }

    $dlg=New-Object System.Windows.Forms.Form
    $dlg.Text="SniperClip"
    $dlg.StartPosition="CenterParent"
    $dlg.FormBorderStyle=[System.Windows.Forms.FormBorderStyle]::FixedDialog
    $dlg.MinimizeBox=$false
    $dlg.MaximizeBox=$false
    $dlg.ShowInTaskbar=$false
    $dlg.AutoSize=$true
    $dlg.AutoSizeMode=[System.Windows.Forms.AutoSizeMode]::GrowAndShrink
    $dlg.Padding=New-Object System.Windows.Forms.Padding(14)

    $layout=New-Object System.Windows.Forms.TableLayoutPanel
    $layout.AutoSize=$true
    $layout.AutoSizeMode=[System.Windows.Forms.AutoSizeMode]::GrowAndShrink
    $layout.ColumnCount=1
    $layout.RowCount=2
    $layout.Dock=[System.Windows.Forms.DockStyle]::Fill

    $lbl=New-Object System.Windows.Forms.Label
    $lbl.Text=$message
    $lbl.AutoSize=$true
    $lbl.MaximumSize=New-Object System.Drawing.Size(420,0)
    $lbl.Margin=New-Object System.Windows.Forms.Padding(0,0,0,14)

    $buttons=New-Object System.Windows.Forms.FlowLayoutPanel
    $buttons.AutoSize=$true
    $buttons.Dock=[System.Windows.Forms.DockStyle]::Fill
    $buttons.FlowDirection=[System.Windows.Forms.FlowDirection]::RightToLeft

    $btnNo=New-Object System.Windows.Forms.Button
    $btnNo.Text=$noText
    $btnNo.AutoSize=$true
    $btnNo.DialogResult=[System.Windows.Forms.DialogResult]::No

    $btnYes=New-Object System.Windows.Forms.Button
    $btnYes.Text=$yesText
    $btnYes.AutoSize=$true
    $btnYes.DialogResult=[System.Windows.Forms.DialogResult]::Yes

    [void]$buttons.Controls.Add($btnNo)
    [void]$buttons.Controls.Add($btnYes)
    [void]$layout.Controls.Add($lbl,0,0)
    [void]$layout.Controls.Add($buttons,0,1)
    [void]$dlg.Controls.Add($layout)
    $dlg.AcceptButton=$btnYes
    $dlg.CancelButton=$btnNo
    return $dlg.ShowDialog($owner)
}
New-Item -ItemType Directory -Force -Path $DataDir | Out-Null

