Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class SniperClipSQLite {
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl, CharSet=CharSet.Unicode)]
    public static extern int sqlite3_open16(string filename, out IntPtr db);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    public static extern int sqlite3_close(IntPtr db);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl, CharSet=CharSet.Ansi)]
    public static extern int sqlite3_exec(IntPtr db, string sql, IntPtr callback, IntPtr arg, out IntPtr errmsg);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl, CharSet=CharSet.Unicode)]
    public static extern int sqlite3_prepare16_v2(IntPtr db, string sql, int nByte, out IntPtr stmt, IntPtr pzTail);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    public static extern int sqlite3_step(IntPtr stmt);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    public static extern int sqlite3_finalize(IntPtr stmt);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    public static extern int sqlite3_column_int(IntPtr stmt, int iCol);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    public static extern IntPtr sqlite3_column_text16(IntPtr stmt, int iCol);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    public static extern IntPtr sqlite3_errmsg16(IntPtr db);
}
'@

$script:db=[IntPtr]::Zero
function Db-Quote([string]$value){
    if($null -eq $value){ return "NULL" }
    return "'"+($value.Replace("'","''"))+"'"
}
function Db-Open {
    if($script:db -ne [IntPtr]::Zero){ return }
    $rc=[SniperClipSQLite]::sqlite3_open16($DatabaseFile,[ref]$script:db)
    if($rc -ne 0){ throw "Impossible d'ouvrir la base SQLite (code $rc)." }
    $nullPtr=[IntPtr]::Zero
    $rc=[SniperClipSQLite]::sqlite3_exec($script:db,"PRAGMA foreign_keys=ON;",[IntPtr]::Zero,[IntPtr]::Zero,[ref]$nullPtr)
    if($rc -ne 0){ throw "Impossible d'initialiser SQLite (code $rc)." }
}
function Db-Exec([string]$sql){
    Db-Open
    $stmt=[IntPtr]::Zero
    $rc=[SniperClipSQLite]::sqlite3_prepare16_v2($script:db,$sql,-1,[ref]$stmt,[IntPtr]::Zero)
    if($rc -ne 0){
        $msg="Erreur SQLite prepare (code $rc)."
        try{$msg=[Runtime.InteropServices.Marshal]::PtrToStringUni([SniperClipSQLite]::sqlite3_errmsg16($script:db))}catch{}
        throw $msg
    }
    try{
        $rc=[SniperClipSQLite]::sqlite3_step($stmt)
        if($rc -ne 101 -and $rc -ne 100){
            $msg="Erreur SQLite (code $rc)."
            try{$msg=[Runtime.InteropServices.Marshal]::PtrToStringUni([SniperClipSQLite]::sqlite3_errmsg16($script:db))}catch{}
            throw $msg
        }
    }finally{ [SniperClipSQLite]::sqlite3_finalize($stmt) | Out-Null }
}
function Db-QueryCells {
    Db-Open
    $stmt=[IntPtr]::Zero
    $sql="SELECT idx,name_b64,text_b64,rtf_b64,html_b64,cellback,shortcut,shortcut_mod,shortcut_key FROM cells ORDER BY idx;"
    $rc=[SniperClipSQLite]::sqlite3_prepare16_v2($script:db,$sql,-1,[ref]$stmt,[IntPtr]::Zero)
    if($rc -ne 0){ throw "Erreur SQLite lors de la lecture des cellules (code $rc)." }
    $rows=New-Object System.Collections.Generic.List[object]
    try{
        while(($rc=[SniperClipSQLite]::sqlite3_step($stmt)) -eq 100){
            $vals=New-Object object[] 9
            $vals[0]=[SniperClipSQLite]::sqlite3_column_int($stmt,0)
            for($c=1;$c -le 6;$c++){
                $ptr=[SniperClipSQLite]::sqlite3_column_text16($stmt,$c)
                $vals[$c]=if($ptr -eq [IntPtr]::Zero){""}else{[Runtime.InteropServices.Marshal]::PtrToStringUni($ptr)}
            }
            $vals[7]=[SniperClipSQLite]::sqlite3_column_int($stmt,7)
            $vals[8]=[SniperClipSQLite]::sqlite3_column_int($stmt,8)
            $rows.Add([pscustomobject]@{Index=$vals[0];NameB64=$vals[1];TextB64=$vals[2];RtfB64=$vals[3];HtmlB64=$vals[4];CellBack=$vals[5];Shortcut=$vals[6];ShortcutModifiers=$vals[7];ShortcutKey=$vals[8]})
        }
    }finally{ [SniperClipSQLite]::sqlite3_finalize($stmt) | Out-Null }
    return $rows
}
function Db-GetSetting([string]$key){
    Db-Open
    $stmt=[IntPtr]::Zero
    $sql="SELECT value_b64 FROM settings WHERE key="+(Db-Quote $key)+" LIMIT 1;"
    $rc=[SniperClipSQLite]::sqlite3_prepare16_v2($script:db,$sql,-1,[ref]$stmt,[IntPtr]::Zero)
    if($rc -ne 0){ return $null }
    try{
        if([SniperClipSQLite]::sqlite3_step($stmt) -eq 100){
            $ptr=[SniperClipSQLite]::sqlite3_column_text16($stmt,0)
            if($ptr -ne [IntPtr]::Zero){ return [Runtime.InteropServices.Marshal]::PtrToStringUni($ptr) }
        }
    }finally{ [SniperClipSQLite]::sqlite3_finalize($stmt) | Out-Null }
    return $null
}
function B64([string]$value){
    if($null -eq $value){$value=""}
    return [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($value))
}
function UnB64([string]$value){
    if([string]::IsNullOrEmpty($value)){return ""}
    try{return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($value))}catch{return ""}
}

$columns = 5
$rows = 6
$count = $columns * $rows

$slots=New-Object object[] $count
for($i=0;$i -lt $count;$i++){
    $slots[$i]=[pscustomobject]@{Name="";Text="";Rtf="";Html="";CellBack="";Shortcut="";ShortcutModifiers=0;ShortcutKey=0}
}

function Db-IntegrityOk {
    Db-Open
    $stmt=[IntPtr]::Zero
    $rc=[SniperClipSQLite]::sqlite3_prepare16_v2($script:db,"PRAGMA integrity_check;",-1,[ref]$stmt,[IntPtr]::Zero)
    if($rc -ne 0){ return $false }
    try {
        $step=[SniperClipSQLite]::sqlite3_step($stmt)
        if($step -eq 100){
            $ptr=[SniperClipSQLite]::sqlite3_column_text16($stmt,0)
            if($ptr -ne [IntPtr]::Zero){ return (([Runtime.InteropServices.Marshal]::PtrToStringUni($ptr)) -eq "ok") }
        }
    } finally { [SniperClipSQLite]::sqlite3_finalize($stmt) | Out-Null }
    return $false
}
function Backup-Database {
    $wasOpen = ($script:db -ne [IntPtr]::Zero)
    $closedForBackup = $false
    try {
        if(-not (Test-Path -LiteralPath $DatabaseFile -PathType Leaf)){ return }
        if(-not (Db-IntegrityOk)){ return }
        # Fermer la connexion avant la copie afin que SQLite termine proprement
        # son éventuel WAL. Une copie du seul .db alors que .db-wal existe peut
        # sinon produire une sauvegarde incohérente.
        if($script:db -ne [IntPtr]::Zero){
            [SniperClipSQLite]::sqlite3_close($script:db) | Out-Null
            $script:db=[IntPtr]::Zero
            $closedForBackup=$true
        }
        $backup=Join-Path $DataDir "SniperClip.db.backup"
        Copy-Item -LiteralPath $DatabaseFile -Destination $backup -Force
        Write-SniperClipLog "Sauvegarde automatique de la base créée."
    } catch {
        Write-SniperClipLog ("Sauvegarde automatique impossible : "+$_.Exception.Message) "WARN"
    } finally {
        if($closedForBackup -and $wasOpen){ try { Db-Open } catch { Write-SniperClipLog ("Réouverture de la base après sauvegarde impossible : "+$_.Exception.Message) "ERROR" } }
    }
}
try{
    Db-Open
    # IMPORTANT : Db-Exec prepare une seule instruction SQL à la fois.
    # Les deux CREATE doivent donc être exécutés séparément.
    Db-Exec @"
CREATE TABLE IF NOT EXISTS cells (
 idx INTEGER PRIMARY KEY,
 name_b64 TEXT NOT NULL DEFAULT '',
 text_b64 TEXT NOT NULL DEFAULT '',
 rtf_b64 TEXT NOT NULL DEFAULT '',
 html_b64 TEXT NOT NULL DEFAULT '',
 cellback TEXT NOT NULL DEFAULT '',
 shortcut TEXT NOT NULL DEFAULT '',
 shortcut_mod INTEGER NOT NULL DEFAULT 0,
 shortcut_key INTEGER NOT NULL DEFAULT 0
);
"@
    Db-Exec @"
CREATE TABLE IF NOT EXISTS settings (
 key TEXT PRIMARY KEY,
 value_b64 TEXT NOT NULL DEFAULT ''
);
"@

    $existingRows=@(Db-QueryCells)
    $hasCells=($existingRows.Count -gt 0)
    $hasMeaningfulDbData=$false
    foreach($item in $existingRows){
        if(-not [string]::IsNullOrEmpty([string]$item.NameB64) -or -not [string]::IsNullOrEmpty([string]$item.TextB64) -or -not [string]::IsNullOrEmpty([string]$item.RtfB64) -or -not [string]::IsNullOrEmpty([string]$item.HtmlB64) -or -not [string]::IsNullOrEmpty([string]$item.CellBack) -or -not [string]::IsNullOrEmpty([string]$item.Shortcut) -or [int]$item.ShortcutModifiers -ne 0 -or [int]$item.ShortcutKey -ne 0){
            $hasMeaningfulDbData=$true
            break
        }
    }

    $legacyConfig=Join-Path $DataDir "config.json"
    $legacySlots=Join-Path $DataDir "slots.json"
    $legacyFilesExist=(Test-Path $legacyConfig) -or (Test-Path $legacySlots)
    $useLegacyMigration=($legacyFilesExist -and (-not $hasMeaningfulDbData))

    if($hasCells -and -not $useLegacyMigration){
        foreach($item in $existingRows){
            $idx=[int]$item.Index
            if($idx -ge 0 -and $idx -lt $count){
                $slots[$idx]=[pscustomobject]@{
                    Name=UnB64 $item.NameB64; Text=UnB64 $item.TextB64; Rtf=UnB64 $item.RtfB64; Html=UnB64 $item.HtmlB64
                    CellBack=[string]$item.CellBack; Shortcut=[string]$item.Shortcut; ShortcutModifiers=[int]$item.ShortcutModifiers; ShortcutKey=[int]$item.ShortcutKey
                }
            }
        }
    }else{
        $legacyRoot=$null
        if(Test-Path $legacyConfig){try{$legacyRoot=Get-Content $legacyConfig -Raw | ConvertFrom-Json}catch{}}
        if($null -eq $legacyRoot -and (Test-Path $legacySlots)){try{$legacyRoot=Get-Content $legacySlots -Raw | ConvertFrom-Json}catch{}}
        if($null -ne $legacyRoot){
            $sourceCells=$null
            if($null -ne $legacyRoot.Cells){$sourceCells=@($legacyRoot.Cells)}
            elseif($legacyRoot -is [array]){$sourceCells=@($legacyRoot)}
            if($null -ne $sourceCells){
                foreach($item in $sourceCells){
                    $idx=[int]$item.Index
                    if($idx -ge 0 -and $idx -lt $count){
                        $slots[$idx]=[pscustomobject]@{
                            Name=[string]$item.Name; Text=[string]$item.Text; Rtf=[string]$item.Rtf; Html=[string]$item.Html
                            CellBack=[string]$item.CellBack; Shortcut=[string]$item.Shortcut; ShortcutModifiers=[int]$item.ShortcutModifiers; ShortcutKey=[int]$item.ShortcutKey
                        }
                    }
                }
            }
            if($null -ne $legacyRoot.Theme){$legacyRoot.Theme | ConvertTo-Json -Depth 4 | Set-Variable -Name __legacyThemeJson -Scope Script}
            if($null -ne $legacyRoot.Window){$legacyRoot.Window | ConvertTo-Json -Depth 4 | Set-Variable -Name __legacyWindowJson -Scope Script}
            if($null -ne $legacyRoot.Grid){$legacyRoot.Grid | ConvertTo-Json -Depth 4 | Set-Variable -Name __legacyGridJson -Scope Script}
        }
    }
}catch{
    [System.Windows.Forms.MessageBox]::Show((T "Impossible d'initialiser la base de données SniperClip :")+" $($_.Exception.Message)","SniperClip",[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
    throw
}

# La base est maintenant initialisée et ses tables existent : c'est le bon moment
# pour créer la sauvegarde automatique de la base précédente.
Backup-Database

function Save-Slots {
    if($script:isInitializing){ return }
    try{
        Db-Open
        Db-Exec "BEGIN IMMEDIATE;"
        try{
            # Remplacement complet des cellules dans la transaction : compatible avec les versions SQLite Windows.
            $currentSql = "DELETE FROM cells;"
            Db-Exec $currentSql
            for($i=0;$i -lt $count;$i++){
                $slot=$slots[$i]
                $currentSql="INSERT INTO cells(idx,name_b64,text_b64,rtf_b64,html_b64,cellback,shortcut,shortcut_mod,shortcut_key) VALUES("+
                    $i+","+(Db-Quote (B64 ([string]$slot.Name)))+","+(Db-Quote (B64 ([string]$slot.Text)))+","+(Db-Quote (B64 ([string]$slot.Rtf)))+","+(Db-Quote (B64 ([string]$slot.Html)))+","+(Db-Quote ([string]$slot.CellBack))+","+(Db-Quote ([string]$slot.Shortcut))+","+[int]$slot.ShortcutModifiers+","+[int]$slot.ShortcutKey+");"
                Db-Exec $currentSql
            }
            if($null -ne $form){
                $bounds=$form.Bounds
                $window=[pscustomobject]@{Left=[int]$bounds.Left;Top=[int]$bounds.Top;Width=[int]$bounds.Width;Height=[int]$bounds.Height;State=[string]$form.WindowState}
                $gridConfig=[pscustomobject]@{Columns=[int]$columns;Rows=[int]$rows;HeaderHeight=[int]$headerHeight;ColumnWeights=@($columnWeights | ForEach-Object {[double]$_});RowWeights=@($rowWeights | ForEach-Object {[double]$_})}
                # Les clés Window/Grid/Theme sont uniques. On remplace leurs anciennes
                # valeurs avant de les réinsérer afin d'éviter UNIQUE constraint failed.
                $currentSql="DELETE FROM settings;"
                Db-Exec $currentSql
                foreach($pair in @(@("Window",($window|ConvertTo-Json -Compress -Depth 6)),@("Grid",($gridConfig|ConvertTo-Json -Compress -Depth 6)),@("Theme",($theme|ConvertTo-Json -Compress -Depth 6)),@("Language",$script:Language))){
                    $currentSql="INSERT INTO settings(key,value_b64) VALUES("+(Db-Quote $pair[0])+","+(Db-Quote (B64 $pair[1]))+");"
                    Db-Exec $currentSql
                }
            }
            Db-Exec "COMMIT;"
        }catch{Db-Exec "ROLLBACK;"; throw}
    }catch{
        # Ne pas interrompre SniperClip, mais conserver la cause exacte + la dernière requête SQL.
        try {
            Db-Exec "ROLLBACK;" -ErrorAction SilentlyContinue
        } catch {}
        try {
            $errPath=Join-Path $DataDir "save_error.txt"
            $stamp=(Get-Date).ToString("yyyy-MM-dd HH:mm:ss")
            $sqlInfo = if($null -ne $currentSql){ " SQL=$currentSql" } else { "" }
            Add-Content -LiteralPath $errPath -Value ("[$stamp] " + $_.Exception.ToString() + $sqlInfo) -Encoding UTF8
            Write-SniperClipLog (("Erreur de sauvegarde : "+$_.Exception.Message)) "ERROR"
        } catch {}
    }
}

try {
    $lj=Db-GetSetting "Language"
    if($lj){ $candidate=UnB64 $lj; if($candidate -in @("fr","en","es","de","pl","ja","it")){ $script:Language=$candidate } }
}catch{}
$savedConfig=[pscustomobject]@{Window=$null;Grid=$null;Theme=$null}
try{
    $wj=Db-GetSetting "Window"; if($wj){$savedConfig.Window=(UnB64 $wj)|ConvertFrom-Json}
    $gj=Db-GetSetting "Grid"; if($gj){$savedConfig.Grid=(UnB64 $gj)|ConvertFrom-Json}
    $tj=Db-GetSetting "Theme"; if($tj){$savedConfig.Theme=(UnB64 $tj)|ConvertFrom-Json}
}catch{}
if($null -eq $savedConfig.Theme -and $script:__legacyThemeJson){try{$savedConfig.Theme=$script:__legacyThemeJson|ConvertFrom-Json}catch{}}
if($null -eq $savedConfig.Window -and $script:__legacyWindowJson){try{$savedConfig.Window=$script:__legacyWindowJson|ConvertFrom-Json}catch{}}
if($null -eq $savedConfig.Grid -and $script:__legacyGridJson){try{$savedConfig.Grid=$script:__legacyGridJson|ConvertFrom-Json}catch{}}
Write-SniperClipLog ("Démarrage SniperClip. Langue="+$script:Language)

if($useLegacyMigration){
    try{
        $script:isInitializing=$false
        Save-Slots
        $script:isInitializing=$true
        foreach($oldName in @("config.json","slots.json")){
            $oldPath=Join-Path $DataDir $oldName
            if(Test-Path $oldPath){
                $backup=$oldPath+".backup"
                if(Test-Path $backup){Remove-Item -LiteralPath $backup -Force -ErrorAction SilentlyContinue}
                Move-Item -LiteralPath $oldPath -Destination $backup -Force
            }
        }
    }catch{ $script:isInitializing=$true }
}

function Theme-Color([string]$value){
    try { return [System.Drawing.ColorTranslator]::FromHtml($value) }
    catch { return [System.Drawing.Color]::White }
}

function Apply-Theme {
    $header.BackColor=Theme-Color $theme.HeaderBack
    $gridHost.BackColor=Theme-Color $theme.GridBack
    $grid.BackColor=Theme-Color $theme.GridBack
    $title.ForeColor=Theme-Color $theme.HeaderText
    $help.ForeColor=Theme-Color $theme.HeaderText

    if($buttons.Count -gt 0){
        for($i=0;$i -lt $buttons.Count;$i++){
            $cellBack=[string]$slots[$i].CellBack
            if([string]::IsNullOrWhiteSpace($cellBack)){
                $cellBack=[string]$theme.CellBack
            }
            $buttons[$i].BackColor=Theme-Color $cellBack
            $buttons[$i].ForeColor=Theme-Color $theme.CellText
            $buttons[$i].FlatAppearance.BorderColor=Theme-Color $theme.GridLine
        }
    }
}

function Choose-ThemeColor([string]$label,[string]$current){
    $cd=New-Object System.Windows.Forms.ColorDialog
    $cd.FullOpen=$true
    $cd.Color=Theme-Color $current

    # La boîte système de couleur n'autorise pas un titre personnalisé.
    # On conserve donc son comportement standard et on associe le libellé
    # à la fenêtre d'appel via un petit formulaire parent.
    $owner=New-Object System.Windows.Forms.Form
    $owner.Text=(T "SniperClip - ")+ $label
    $owner.StartPosition="CenterParent"
    $owner.ClientSize=New-Object System.Drawing.Size(1,1)
    $owner.FormBorderStyle="None"
    $owner.ShowInTaskbar=$false
    $owner.Opacity=0
    $owner.Show()
    $result=$cd.ShowDialog($owner)
    $owner.Close()
    $owner.Dispose()

    if($result -eq [System.Windows.Forms.DialogResult]::OK){
        return [System.Drawing.ColorTranslator]::ToHtml($cd.Color)
    }
    return $current
}

