# Restaurer la personnalisation du thème enregistrée dans SQLite.
# Les versions précédentes chargeaient bien la valeur "Theme" depuis la base,
# mais ne la réappliquaient pas à l'objet $theme au démarrage.
if($null -ne $savedConfig.Theme){
    foreach($themeKey in @("HeaderBack","HeaderText","GridBack","CellBack","CellText","GridLine")){
        try {
            $savedValue = [string]$savedConfig.Theme.$themeKey
            if(-not [string]::IsNullOrWhiteSpace($savedValue)){ $theme.$themeKey=$savedValue }
        } catch {}
    }
}

