function Shortcut-Text([int]$modifiers,[int]$vk) {
    $parts=New-Object System.Collections.Generic.List[string]
    if(($modifiers -band 0x0002)-ne 0){$parts.Add("Ctrl")}
    if(($modifiers -band 0x0001)-ne 0){$parts.Add("Alt")}
    if(($modifiers -band 0x0004)-ne 0){$parts.Add("Shift")}
    if(($modifiers -band 0x0008)-ne 0){$parts.Add("Win")}
    try{
        $k=[System.Windows.Forms.Keys]$vk
        $parts.Add($k.ToString())
    }catch{}
    return ($parts -join "+")
}

function Set-CellShortcut([int]$cellIndex) {
    $dlg=New-Object System.Windows.Forms.Form
    $dlg.Text=(T "SniperClip - raccourci de la cellule ")+($cellIndex+1)
    $dlg.StartPosition="CenterParent"
    $dlg.Size=New-Object System.Drawing.Size(430,210)
    $dlg.MinimizeBox=$false
    $dlg.MaximizeBox=$false
    $dlg.ShowInTaskbar=$false

    $label=New-Object System.Windows.Forms.Label
    $label.Text=(T "Appuyez sur la combinaison de touches à attribuer :")
    $label.Location=New-Object System.Drawing.Point(15,15)
    $label.AutoSize=$true

    $display=New-Object System.Windows.Forms.TextBox
    $display.Location=New-Object System.Drawing.Point(15,45)
    $display.Size=New-Object System.Drawing.Size(380,28)
    $display.ReadOnly=$true
    $display.TabStop=$false

    $info=New-Object System.Windows.Forms.Label
    $info.Text=(T "Un modificateur est obligatoire : Ctrl, Alt, Shift ou Win. Le raccourci fonctionne même si SniperClip est masqué.")
    $info.Location=New-Object System.Drawing.Point(15,80)
    $info.Size=New-Object System.Drawing.Size(380,38)

    $clear=New-Object System.Windows.Forms.Button
    $clear.Text=(T "Supprimer le raccourci")
    $clear.Location=New-Object System.Drawing.Point(15,125)
    $clear.Size=New-Object System.Drawing.Size(140,32)

    $ok=New-Object System.Windows.Forms.Button
    $ok.Text=(T "Enregistrer")
    $ok.Location=New-Object System.Drawing.Point(220,125)
    $ok.Size=New-Object System.Drawing.Size(85,32)
    $ok.DialogResult=[System.Windows.Forms.DialogResult]::OK

    $cancel=New-Object System.Windows.Forms.Button
    $cancel.Text=(T "Annuler")
    $cancel.Location=New-Object System.Drawing.Point(310,125)
    $cancel.Size=New-Object System.Drawing.Size(85,32)
    $cancel.DialogResult=[System.Windows.Forms.DialogResult]::Cancel

    $state=[pscustomobject]@{
        Modifiers=[int]$slots[$cellIndex].ShortcutModifiers
        Key=[int]$slots[$cellIndex].ShortcutKey
        Clear=$false
    }
    if($state.Key -gt 0){$display.Text=Shortcut-Text $state.Modifiers $state.Key}

    $dlg.Add_KeyDown({
        $mods=0
        if($_.Control){$mods=$mods -bor 0x0002}
        if($_.Alt){$mods=$mods -bor 0x0001}
        if($_.Shift){$mods=$mods -bor 0x0004}
        # Win is intentionally not detected through KeyEventArgs here because
        # the global RegisterHotKey API handles it differently.
        $key=[int]$_.KeyCode

        if($key -in @([int][System.Windows.Forms.Keys]::ControlKey,[int][System.Windows.Forms.Keys]::Menu,[int][System.Windows.Forms.Keys]::ShiftKey,[int][System.Windows.Forms.Keys]::LWin,[int][System.Windows.Forms.Keys]::RWin)){
            return
        }
        if($mods -eq 0){return}

        $state.Modifiers=$mods
        $state.Key=$key
        $state.Clear=$false
        $display.Text=Shortcut-Text $mods $key
        $_.SuppressKeyPress=$true
        $_.Handled=$true
    })

    $clear.Add_Click({
        $state.Modifiers=0
        $state.Key=0
        $state.Clear=$true
        $display.Text=""
    })

    $dlg.Controls.AddRange(@($label,$display,$info,$clear,$ok,$cancel))
    $dlg.AcceptButton=$ok
    $dlg.CancelButton=$cancel
    $dlg.KeyPreview=$true

    $result=$dlg.ShowDialog($form)
    if($result -eq [System.Windows.Forms.DialogResult]::OK){
        # Le raccourci global Ctrl+Alt+V est réservé à SniperClip.
        if($state.Key -eq 0x56 -and (($state.Modifiers -band 0x0003) -eq 0x0003)){
            [System.Windows.Forms.MessageBox]::Show($form,(T "Le raccourci Ctrl+Alt+V est réservé à SniperClip."),"SniperClip",[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
            $dlg.Dispose()
            return
        }
        # Check duplicates among other cells.
        if($state.Key -gt 0){
            for($i=0;$i -lt $count;$i++){
                if($i -ne $cellIndex -and [int]$slots[$i].ShortcutKey -eq $state.Key -and [int]$slots[$i].ShortcutModifiers -eq $state.Modifiers){
                    [System.Windows.Forms.MessageBox]::Show($form,(T "Ce raccourci est déjà attribué à la cellule ")+($i+1)+".","SniperClip",[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
                    $dlg.Dispose()
                    return
                }
            }

            # Le hook clavier global n'a pas besoin de réserver le raccourci
            # auprès de Windows. On vérifie uniquement les doublons SniperClip.
            # Les raccourcis système éventuellement utilisés par Windows ou
            # une autre application restent prioritaires.
            $slots[$cellIndex].ShortcutModifiers=$state.Modifiers
            $slots[$cellIndex].ShortcutKey=$state.Key
            $slots[$cellIndex].Shortcut=Shortcut-Text $state.Modifiers $state.Key
        }else{
            $slots[$cellIndex].ShortcutModifiers=0
            $slots[$cellIndex].ShortcutKey=0
            $slots[$cellIndex].Shortcut=""
        }

        Save-Slots
        Update-Button $cellIndex
    }
    $dlg.Dispose()
}

function Set-ClipboardFromSlot([int]$index){
    $slot=$slots[$index]

    # Build the clipboard explicitly so that text, RTF and HTML can coexist.
    # This is important for hyperlinks: many applications prefer HTML when it
    # is available, while Outlook/Word can still use RTF. Plain Unicode text
    # remains available as the fallback.
    $data=New-Object System.Windows.Forms.DataObject
    $plain=[string]$slot.Text
    $rtf=[string]$slot.Rtf
    $html=[string]$slot.Html

    $data.SetData([System.Windows.Forms.DataFormats]::UnicodeText,$plain)
    $data.SetData([System.Windows.Forms.DataFormats]::Text,$plain)

    if(-not [string]::IsNullOrEmpty($rtf)){
        $data.SetData([System.Windows.Forms.DataFormats]::Rtf,$rtf)
    }
    if(-not [string]::IsNullOrEmpty($html)){
        # Stored HTML is already in Windows CF_HTML clipboard format when it
        # comes from another application, so preserve it unchanged.
        $data.SetData([System.Windows.Forms.DataFormats]::Html,$html)
    }

    [System.Windows.Forms.Clipboard]::SetDataObject($data,$true)
}

function Edit-Slot([int]$cellIndex){
    Hide-Preview
    $script:previewIndex=-1

    $currentName=[string]$slots[$cellIndex].Name
    $currentText=[string]$slots[$cellIndex].Text
    $currentRtf=[string]$slots[$cellIndex].Rtf
    $currentHtml=[string]$slots[$cellIndex].Html
    $currentCellBack=[string]$slots[$cellIndex].CellBack
    if([string]::IsNullOrWhiteSpace($currentCellBack)){
        $currentCellBack=[string]$theme.CellBack
    }
    $editCellState=[pscustomobject]@{Value=$currentCellBack}

    $dlg=New-Object System.Windows.Forms.Form
    $dlg.Text=(T "SniperClip - modifier la cellule ")+($cellIndex+1)
    $dlg.StartPosition="CenterParent"
    $dlg.ClientSize=New-Object System.Drawing.Size(700,540)
    $dlg.MinimumSize=New-Object System.Drawing.Size(620,500)
    $dlg.AutoScaleMode=[System.Windows.Forms.AutoScaleMode]::Font
    $dlg.MinimizeBox=$false
    $dlg.MaximizeBox=$true
    $dlg.ShowInTaskbar=$false

    # 6 lignes indépendantes :
    # libellé / nom / aide / éditeur extensible / outils / actions.
    # Cela évite tout chevauchement lorsque la fenêtre est redimensionnée.
    $layout=New-Object System.Windows.Forms.TableLayoutPanel
    $layout.Dock="Fill"
    $layout.Padding=New-Object System.Windows.Forms.Padding(15)
    $layout.ColumnCount=1
    $layout.RowCount=6
    $layout.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Percent,100)))
    $layout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute,24)))
    $layout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute,30)))
    $layout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute,27)))
    $layout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Percent,100)))
    $layout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute,43)))
    $layout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute,48)))

    $nameLabel=New-Object System.Windows.Forms.Label
    $nameLabel.Text=(T "Nom de la cellule")
    $nameLabel.Dock="Fill"
    $nameLabel.TextAlign="MiddleLeft"

    $nameEditor=New-Object System.Windows.Forms.TextBox
    $nameEditor.Dock="Fill"
    $nameEditor.Text=$currentName
    $nameEditor.Margin=New-Object System.Windows.Forms.Padding(0,1,0,3)

    $info=New-Object System.Windows.Forms.Label
    $info.Text=(T "Collez avec Ctrl+V : la mise en forme est conservée.  Ctrl+B = gras, Ctrl+I = italique.")
    $info.Dock="Fill"
    $info.TextAlign="MiddleLeft"
    $info.AutoEllipsis=$true

    $textEditor=New-Object System.Windows.Forms.RichTextBox
    $textEditor.Dock="Fill"
    $textEditor.Font=New-Object System.Drawing.Font("Segoe UI",11)
    $textEditor.DetectUrls=$true
    $textEditor.ScrollBars="Vertical"
    $textEditor.AcceptsTab=$true
    $textEditor.Margin=New-Object System.Windows.Forms.Padding(0,2,0,5)
    $textEditor.BackColor=[System.Drawing.Color]::White
    $textEditor.ForeColor=[System.Drawing.Color]::Black

    # OneNote peut placer du texte Unicode et une image (EnhancedMetafile)
    # dans le presse-papiers, sans fournir de RTF. Le comportement natif
    # de RichTextBox peut alors privilégier l'image. Lorsque Ctrl+V est
    # utilisé et qu'aucun RTF n'est disponible, donner priorité au texte
    # Unicode. Si un HTML est disponible, le conserver aussi afin de pouvoir
    # restituer correctement les hyperliens lors d'une copie depuis SniperClip.
    $script:editClipboardHtml=$currentHtml
    $textEditor.Add_KeyDown({
        if($_.Control -and $_.KeyCode -eq [System.Windows.Forms.Keys]::V){
            try{
                $data=[System.Windows.Forms.Clipboard]::GetDataObject()
                if($null -ne $data -and $data.GetDataPresent([System.Windows.Forms.DataFormats]::Html)){
                    try{
                        $script:editClipboardHtml=[string]$data.GetData([System.Windows.Forms.DataFormats]::Html)
                    }catch{
                        $script:editClipboardHtml=""
                    }
                }else{
                    $script:editClipboardHtml=""
                }

                $hasRtf=($null -ne $data -and $data.GetDataPresent([System.Windows.Forms.DataFormats]::Rtf))
                $hasUnicode=($null -ne $data -and ($data.GetDataPresent([System.Windows.Forms.DataFormats]::UnicodeText) -or $data.GetDataPresent([System.Windows.Forms.DataFormats]::Text)))
                if(-not $hasRtf -and $hasUnicode){
                    $_.SuppressKeyPress=$true
                    $_.Handled=$true
                    $pasteText=[System.Windows.Forms.Clipboard]::GetText([System.Windows.Forms.TextDataFormat]::UnicodeText)
                    $textEditor.SelectedText=$pasteText
                }
            }catch{
                $script:editClipboardHtml=""
            }
        }
    })

    # Toujours afficher le contenu texte. Si le RTF est valide, on le conserve ;
    # sinon on retombe proprement sur le texte brut.
    $loadedRtf=$false
    if(-not [string]::IsNullOrWhiteSpace($currentRtf)){
        try{
            $textEditor.Rtf=$currentRtf
            $loadedRtf=$true
        }catch{
            $loadedRtf=$false
        }
    }
    if(-not $loadedRtf -or ($textEditor.TextLength -eq 0 -and -not [string]::IsNullOrEmpty($currentText))){
        $textEditor.Text=$currentText
    }

    # Barre d'outils indépendante.
    $tools=New-Object System.Windows.Forms.FlowLayoutPanel
    $tools.Dock="Fill"
    $tools.WrapContents=$false
    $tools.FlowDirection="LeftToRight"
    $tools.AutoScroll=$true
    $tools.Padding=New-Object System.Windows.Forms.Padding(0,4,0,2)

    $bold=New-Object System.Windows.Forms.Button
