function Update-Button([int]$index){
    $b=$buttons[$index]
    $cellBack=[string]$slots[$index].CellBack
    if([string]::IsNullOrWhiteSpace($cellBack)){
        $cellBack=[string]$theme.CellBack
    }
    $b.BackColor=Theme-Color $cellBack
    $b.ForeColor=Theme-Color $theme.CellText
    $b.AutoEllipsis=$false
    $b.TextAlign="MiddleCenter"

    if([string]::IsNullOrWhiteSpace([string]$slots[$index].Text)){
        $name=[string]$slots[$index].Name
        if([string]::IsNullOrWhiteSpace($name)){$name=($index+1).ToString()}
        $b.Text=$name
    }else{
        $b.Text=Get-CellDisplayText $index
    }

    $size=10.0
    if($b.Width -lt 120 -or $b.Height -lt 48){$size=9.0}
    if($b.Width -lt 75 -or $b.Height -lt 36){$size=8.0}
    $b.Font=New-Object System.Drawing.Font("Segoe UI",$size)

    # À partir d'une hauteur réduite, une seule ligne est utilisée.
    # Cela évite que le centrage vertical coupe les lignes supérieure/inférieure.
    if($b.Height -lt 42){
        $b.TextAlign="MiddleCenter"
    }
}

function Update-AllButtons {
    if($buttons.Count -ne $count){return}
    for($j=0;$j -lt $count;$j++){ Update-Button $j }
}

$script:previewForm=$null
$previewTimer=New-Object System.Windows.Forms.Timer
$previewTimer.Interval=450
$script:previewIndex=-1
$previewMonitor=New-Object System.Windows.Forms.Timer
$previewMonitor.Interval=50

function Hide-Preview {
    $previewTimer.Stop()
    $previewMonitor.Stop()
    $script:previewIndex=-1
    if($null -ne $script:previewForm){
        $script:previewForm.Hide()
    }
}

function Show-Preview([int]$index) {
    if($index -lt 0 -or $index -ge $buttons.Count){ Hide-Preview; return }

    $slot=$slots[$index]
    if([string]::IsNullOrWhiteSpace($slot.Text) -and [string]::IsNullOrEmpty($slot.Rtf)){
        Hide-Preview
        return
    }

    # One and only one preview form for the whole application session.
    if($null -eq $script:previewForm){
        $pf=New-Object System.Windows.Forms.Form
        $pf.FormBorderStyle="FixedToolWindow"
        $pf.StartPosition="Manual"
        $pf.ShowInTaskbar=$false
        $pf.TopMost=$false
        $pf.ShowIcon=$false
        $pf.ControlBox=$false
        $pf.Size=New-Object System.Drawing.Size(420,240)

        $title=New-Object System.Windows.Forms.Label
        $title.Location=New-Object System.Drawing.Point(10,8)
        $title.Size=New-Object System.Drawing.Size(390,25)
        $title.Font=New-Object System.Drawing.Font("Segoe UI Semibold",10)

        $box=New-Object System.Windows.Forms.RichTextBox
        $box.Location=New-Object System.Drawing.Point(10,38)
        $box.Size=New-Object System.Drawing.Size(390,190)
        $box.ReadOnly=$true
        $box.TabStop=$false
        $box.BackColor=[System.Drawing.Color]::White
        $box.ScrollBars="Vertical"
        $box.DetectUrls=$true

        $pf.Controls.AddRange(@($title,$box))
        $pf.Tag=@{Title=$title;Box=$box}

        # Do not let the preview become a second interactive window.
        $pf.Add_Activated({ $form.Activate() })
        $pf.Add_MouseDown({ Hide-Preview })
        $title.Add_MouseDown({ Hide-Preview })
        $box.Add_MouseDown({ Hide-Preview })

        $script:previewForm=$pf
    }

    $pf=$script:previewForm
    $pf.Tag.Title.Text=if([string]::IsNullOrWhiteSpace($slot.Name)){(T "Cellule ")+($index+1)}else{$slot.Name}

    if(-not [string]::IsNullOrEmpty($slot.Rtf)){
        try{$pf.Tag.Box.Rtf=$slot.Rtf}
        catch{$pf.Tag.Box.Text=$slot.Text}
    }else{
        $pf.Tag.Box.Text=$slot.Text
    }

    $pos=[System.Windows.Forms.Cursor]::Position
    $screen=[System.Windows.Forms.Screen]::FromPoint($pos)
    $area=$screen.WorkingArea
    $px=$pos.X+14
    $py=$pos.Y+14
    if($px+$pf.Width -gt $area.Right){$px=$pos.X-$pf.Width-14}
    if($py+$pf.Height -gt $area.Bottom){$py=$pos.Y-$pf.Height-14}
    if($px -lt $area.Left){$px=$area.Left}
    if($py -lt $area.Top){$py=$area.Top}
    $pf.Location=New-Object System.Drawing.Point($px,$py)

    if(-not $pf.Visible){
        $pf.Show($form)
    }
    $pf.BringToFront()
}

$previewTimer.Add_Tick({
    $previewTimer.Stop()
    if($script:previewIndex -ge 0){
        Show-Preview $script:previewIndex
        $previewMonitor.Start()
    }
})

$previewMonitor.Add_Tick({
    if($script:previewIndex -lt 0){
        $previewMonitor.Stop()
        return
    }

    $idx=$script:previewIndex
    if($idx -ge $buttons.Count){
        Hide-Preview
        return
    }

    $mouse=[System.Windows.Forms.Cursor]::Position
    $cellRect=$buttons[$idx].RectangleToScreen($buttons[$idx].ClientRectangle)

    # The preview itself is deliberately ignored here: the source cell is
    # the only area that keeps the preview alive.
    if(-not $cellRect.Contains($mouse)){
        Hide-Preview
    }
})

