# Quadrillage et redimensionnement a la souris
$script:isResizing = $false
$script:resizeMode = ""
$script:resizeIndex = -1
$script:resizeStart = 0
$script:resizeStartA = 0
$script:resizeStartB = 0
$script:suppressNextClick = $false

function Apply-Layout {
    if ($buttons.Count -ne $count) { return }

    $availableW=[math]::Max($columns,$gridHost.ClientSize.Width)
    $availableH=[math]::Max($rows,$gridHost.ClientSize.Height)
    $sumW=0.0; foreach($v in $columnWeights){$sumW += [double]$v}
    $sumH=0.0; foreach($v in $rowWeights){$sumH += [double]$v}

    $widths=New-Object int[] $columns
    $heights=New-Object int[] $rows
    $used=0
    for($c=0;$c -lt $columns;$c++){
        $v=if($c -eq $columns-1){$availableW-$used}else{[int][math]::Floor($availableW*$columnWeights[$c]/$sumW)}
        $widths[$c]=[math]::Max(1,$v);$used+=$widths[$c]
    }
    $used=0
    for($r=0;$r -lt $rows;$r++){
        $v=if($r -eq $rows-1){$availableH-$used}else{[int][math]::Floor($availableH*$rowWeights[$r]/$sumH)}
        $heights[$r]=[math]::Max(1,$v);$used+=$heights[$r]
    }

    $grid.Size=New-Object System.Drawing.Size($availableW,$availableH)
    $y=0
    for($r=0;$r -lt $rows;$r++){
        $x=0
        for($c=0;$c -lt $columns;$c++){
            $i=($r*$columns)+$c
            $buttons[$i].SetBounds($x,$y,$widths[$c],$heights[$r])
            $x+=$widths[$c]
        }
        $y+=$heights[$r]
    }
}

function Capture-CurrentProportions {
    if ($buttons.Count -ne $count) { return }

    for ($c=0; $c -lt $columns; $c++) {
        $columnWeights[$c] = [double][math]::Max(1,$buttons[$c].Width)
    }
    for ($r=0; $r -lt $rows; $r++) {
        $rowWeights[$r] = [double][math]::Max(1,$buttons[$r*$columns].Height)
    }
}

function Begin-Resize([string]$mode,[int]$index,[int]$pos) {
    Capture-CurrentProportions

    $script:isResizing = $true
    $script:resizeMode = $mode
    $script:resizeIndex = $index
    $script:resizeStart = $pos
    $script:suppressNextClick = $true

    if ($mode -eq "vertical") {
        $script:resizeStartA = $buttons[$index].Width
        $script:resizeStartB = $buttons[$index+1].Width
    } else {
        $script:resizeStartA = $buttons[$index*$columns].Height
        $script:resizeStartB = $buttons[($index+1)*$columns].Height
    }
}

function Move-Resize([int]$pos) {
    if (-not $script:isResizing) { return }

    $delta = $pos - $script:resizeStart
    $min = 30
    $total = $script:resizeStartA + $script:resizeStartB

    $a = [int]($script:resizeStartA + $delta)
    $a = [math]::Max($min,[math]::Min($total-$min,$a))
    $b = $total - $a

    if ($script:resizeMode -eq "vertical") {
        $columnWeights[$script:resizeIndex] = [double]$a
        $columnWeights[$script:resizeIndex+1] = [double]$b
    } else {
        $rowWeights[$script:resizeIndex] = [double]$a
        $rowWeights[$script:resizeIndex+1] = [double]$b
    }

    Apply-Layout
    Update-AllButtons
}

function End-Resize {
    $script:isResizing = $false
    $script:resizeMode = ""
    $script:resizeIndex = -1
    Save-Slots
}

function Get-ResizeHit([int]$idx,[int]$x,[int]$y) {
    $c=$idx%$columns
    $r=[math]::Floor($idx/$columns)
    $t=5

    if ($c -lt $columns-1 -and $x -ge $buttons[$idx].Width-$t) {
        return @{Mode="vertical";Index=$c}
    }
    if ($c -gt 0 -and $x -le $t) {
        return @{Mode="vertical";Index=$c-1}
    }
    if ($r -lt $rows-1 -and $y -ge $buttons[$idx].Height-$t) {
        return @{Mode="horizontal";Index=$r}
    }
    if ($r -gt 0 -and $y -le $t) {
        return @{Mode="horizontal";Index=$r-1}
    }
    return $null
}

