$buttons = @()
for ($i=0; $i -lt $count; $i++) {
    $b = New-Object System.Windows.Forms.Button
    $b.FlatStyle = "Flat"
    $b.FlatAppearance.BorderSize = 1
    $b.FlatAppearance.BorderColor = [System.Drawing.Color]::Silver
    $b.BackColor = [System.Drawing.Color]::White
    $b.Font = New-Object System.Drawing.Font("Segoe UI",10)
    $b.TextAlign = "MiddleCenter"
    $b.Tag = $i
    $b.TabStop = $false
    $b.AutoEllipsis = $true
    $b.Padding = New-Object System.Windows.Forms.Padding(3)
    $b.Add_MouseEnter({
        $idx=[int]$this.Tag
        if($script:previewIndex -ne $idx){
            Hide-Preview
            $script:previewIndex=$idx
            $previewTimer.Stop()
            $previewTimer.Start()
            $previewMonitor.Start()
        }
    })
    $b.Add_MouseLeave({
        if($script:previewIndex -eq [int]$this.Tag){
            Hide-Preview
        }
        if(-not $script:isResizing){$this.Cursor=[System.Windows.Forms.Cursors]::Default}
    })
    $b.Add_MouseMove({
        if(-not $script:isResizing -and $script:previewIndex -ne [int]$this.Tag){
            Hide-Preview
            $script:previewIndex=[int]$this.Tag
            $previewTimer.Stop()
            $previewTimer.Start()
            $previewMonitor.Start()
        }

        if ($script:isResizing) {
            if ($script:resizeMode -eq "vertical") { $this.Cursor=[System.Windows.Forms.Cursors]::SizeWE; Move-Resize $_.X }
            else { $this.Cursor=[System.Windows.Forms.Cursors]::SizeNS; Move-Resize $_.Y }
            return
        }
        $hit=Get-ResizeHit ([int]$this.Tag) $_.X $_.Y
        if ($null -ne $hit) {
            if ($hit.Mode -eq "vertical") { $this.Cursor=[System.Windows.Forms.Cursors]::SizeWE }
            else { $this.Cursor=[System.Windows.Forms.Cursors]::SizeNS }
        } else { $this.Cursor=[System.Windows.Forms.Cursors]::Default }
    })
    $b.Add_MouseDown({
        if ($_.Button -eq [System.Windows.Forms.MouseButtons]::Left) {
            $hit=Get-ResizeHit ([int]$this.Tag) $_.X $_.Y
            if ($null -ne $hit) {
                if ($hit.Mode -eq "vertical") { Begin-Resize "vertical" $hit.Index $_.X }
                else { Begin-Resize "horizontal" $hit.Index $_.Y }
            }
        }
    })
    $b.Add_MouseUp({
        if ($_.Button -eq [System.Windows.Forms.MouseButtons]::Left -and $script:isResizing) { End-Resize }
    })

    $b.Add_Click({
        if ($script:suppressNextClick) { $script:suppressNextClick=$false; return }
        Hide-Preview
        $script:previewIndex=-1
        $idx=[int]$this.Tag

        if(-not [string]::IsNullOrEmpty($slots[$idx].Text) -or -not [string]::IsNullOrEmpty($slots[$idx].Rtf)){
            # Copier uniquement : la fenetre principale reste ouverte.
            Set-ClipboardFromSlot $idx
        }else{
            # Une cellule vide peut toujours etre editee directement.
            Edit-Slot $idx
        }
    })

    $b.Add_MouseUp({
        if($_.Button -eq [System.Windows.Forms.MouseButtons]::Right){
            Hide-Preview
            $script:previewIndex=-1

            $idx=[int]$this.Tag
            $contextMenu.Tag=$idx

            $hasContent=(-not [string]::IsNullOrEmpty($slots[$idx].Text) -or -not [string]::IsNullOrEmpty($slots[$idx].Rtf))
            $hasName=(-not [string]::IsNullOrEmpty($slots[$idx].Name))

            $menuCopy.Enabled=$hasContent
            $menuClear.Enabled=($hasContent -or $hasName)

            $contextMenu.Show($this, $_.Location)
        }
    })

    $buttons += $b
    $grid.Controls.Add($b)
}

for ($i=0; $i -lt $count; $i++) { Update-Button $i }

Apply-Layout



$form.Add_KeyDown({
