        if($form.IsHandleCreated){ [SniperClipNativeWindow]::ShowWindow($form.Handle,0) | Out-Null }
    }
})

# Démarrage automatique avec Windows (utilisateur courant, sans droits administrateur)
# V5.48g : utilisation du dossier Startup Windows et d'un vrai raccourci .lnk.
# Cette méthode est plus robuste que HKCU\...\Run, notamment avec OneDrive et les chemins contenant des espaces.
$script:StartupDir = Join-Path $env:APPDATA "Microsoft\Windows\Start Menu\Programs\Startup"
$script:StartupShortcut = Join-Path $script:StartupDir "SniperClip.lnk"
$script:StartupRunKey = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Run"
$script:StartupValueName = "SniperClip"

function Get-StartupEnabled {
    try {
        # La nouvelle méthode est la référence.
        if(Test-Path -LiteralPath $script:StartupShortcut){ return $true }
        return $false
    } catch { return $false }
}

function Set-StartupEnabled([bool]$enabled) {
    try {
        $vbs = Join-Path $PSScriptRoot "Lancer SniperClip.vbs"
        if($enabled){
            if(-not (Test-Path -LiteralPath $vbs)){
                throw "Le fichier 'Lancer SniperClip.vbs' est introuvable dans le dossier de SniperClip."
            }

            if(-not (Test-Path -LiteralPath $script:StartupDir)){
                New-Item -ItemType Directory -Path $script:StartupDir -Force | Out-Null
            }

            # Crée un raccourci Windows standard vers wscript.exe.
            # Cela évite les problèmes d'interprétation de la valeur HKCU\Run.
            $ws = New-Object -ComObject WScript.Shell
            $shortcut = $ws.CreateShortcut($script:StartupShortcut)
            $shortcut.TargetPath = Join-Path $env:WINDIR "System32\wscript.exe"
            $shortcut.Arguments = '//B //NoLogo "' + $vbs + '"'
            $shortcut.WorkingDirectory = $PSScriptRoot
            $icon = Join-Path $PSScriptRoot "SniperClip.ico"
            if(Test-Path -LiteralPath $icon){ $shortcut.IconLocation = $icon }
            $shortcut.Description = "Démarrer SniperClip avec Windows"
            $shortcut.Save()
            [void][Runtime.InteropServices.Marshal]::ReleaseComObject($shortcut)
            [void][Runtime.InteropServices.Marshal]::ReleaseComObject($ws)

            # Supprime l'ancienne entrée Run pour éviter un double lancement.
            Remove-ItemProperty -Path $script:StartupRunKey -Name $script:StartupValueName -ErrorAction SilentlyContinue
        } else {
            Remove-Item -LiteralPath $script:StartupShortcut -Force -ErrorAction SilentlyContinue
            # Nettoyage de l'ancienne méthode si elle existe encore.
            Remove-ItemProperty -Path $script:StartupRunKey -Name $script:StartupValueName -ErrorAction SilentlyContinue
        }
        return $true
    } catch {
        [System.Windows.Forms.MessageBox]::Show(
            ((T "Impossible de modifier le démarrage automatique de SniperClip :`r`n") + $_.Exception.Message),
            (T "SniperClip - démarrage avec Windows"),
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        ) | Out-Null
        return $false
    }
}

# Export / import de configuration
function Export-Configuration {
    try {
        Save-Slots
        $dlg=New-Object System.Windows.Forms.SaveFileDialog
        $dlg.Title=(T "Exporter la configuration")
        $dlg.Filter=(T "Fichier de configuration SniperClip (*.sniperclip)|*.sniperclip")
        $dlg.DefaultExt="sniperclip"
        $dlg.FileName="SniperClip-configuration.sniperclip"
        if($dlg.ShowDialog($form) -ne [System.Windows.Forms.DialogResult]::OK){ $dlg.Dispose(); return }
        $target=$dlg.FileName
        $dlg.Dispose()
        $tmp=Join-Path $env:TEMP ("SniperClipExport_"+[guid]::NewGuid().ToString())
        New-Item -ItemType Directory -Force -Path $tmp | Out-Null
        # Save-Slots peut avoir alimenté un WAL. Fermer la connexion avant la
        # copie garantit que l'archive contient une base SQLite complète.
        if($script:db -ne [IntPtr]::Zero){ [SniperClipSQLite]::sqlite3_close($script:db) | Out-Null; $script:db=[IntPtr]::Zero }
        Copy-Item -LiteralPath $DatabaseFile -Destination (Join-Path $tmp "SniperClip.db") -Force
        Db-Open
        $manifest="SniperClip configuration export`r`nVersion=5.48k`r`nDate="+(Get-Date).ToString("o")
        Set-Content -LiteralPath (Join-Path $tmp "README.txt") -Value $manifest -Encoding UTF8
        if(Test-Path $target){ Remove-Item $target -Force }
        # Compress-Archive impose l'extension .zip. On crée donc d'abord une archive
        # ZIP temporaire puis on lui donne l'extension .sniperclip pour l'utilisateur.
        $zipTarget=$target + ".tmp.zip"
        if(Test-Path $zipTarget){ Remove-Item $zipTarget -Force }
        Compress-Archive -Path (Join-Path $tmp "*") -DestinationPath $zipTarget -Force
        Move-Item -LiteralPath $zipTarget -Destination $target -Force
        Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue
        Write-SniperClipLog ("Configuration exportée vers "+$target)
    } catch {
        try{Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}catch{}
        [System.Windows.Forms.MessageBox]::Show($form,((T "Impossible d’exporter la configuration :")+" `r`n"+$_.Exception.Message),(T "Export SniperClip"),[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Error)|Out-Null
        Write-SniperClipLog (("Export impossible : "+$_.Exception.Message)) "ERROR"
    }
}
function Import-Configuration {
    try {
        $dlg=New-Object System.Windows.Forms.OpenFileDialog
        $dlg.Title=(T "Importer une configuration")
        $dlg.Filter=(T "Fichier de configuration SniperClip (*.sniperclip)|*.sniperclip")
        if($dlg.ShowDialog($form) -ne [System.Windows.Forms.DialogResult]::OK){$dlg.Dispose();return}
        $source=$dlg.FileName; $dlg.Dispose()
        $tmp=Join-Path $env:TEMP ("SniperClipImport_"+[guid]::NewGuid().ToString())
        New-Item -ItemType Directory -Force -Path $tmp | Out-Null
        # Expand-Archive attend une extension .zip : on travaille sur une copie
        # temporaire portant cette extension, sans changer le fichier utilisateur.
        $zipSource=Join-Path $env:TEMP (([guid]::NewGuid().ToString())+".zip")
        Copy-Item -LiteralPath $source -Destination $zipSource -Force
        Expand-Archive -LiteralPath $zipSource -DestinationPath $tmp -Force
        Remove-Item -LiteralPath $zipSource -Force -ErrorAction SilentlyContinue
        $importDb=Join-Path $tmp "SniperClip.db"
        if(-not (Test-Path $importDb)){throw "SniperClip.db introuvable dans le fichier de configuration."}
        $backup=Join-Path $DataDir "SniperClip.db.before-import.backup"
        Save-Slots
        # Fermer SQLite avant de remplacer le fichier afin de fusionner un
        # éventuel WAL et d'éviter qu'un ancien .db-wal ne réapparaisse au redémarrage.
        if($script:db -ne [IntPtr]::Zero){[SniperClipSQLite]::sqlite3_close($script:db)|Out-Null;$script:db=[IntPtr]::Zero}
        Copy-Item -LiteralPath $DatabaseFile -Destination $backup -Force
        foreach($sidecar in @(($DatabaseFile+"-wal"),($DatabaseFile+"-shm"))){
            if(Test-Path -LiteralPath $sidecar){ Remove-Item -LiteralPath $sidecar -Force -ErrorAction SilentlyContinue }
        }
        Copy-Item -LiteralPath $importDb -Destination $DatabaseFile -Force
        Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue
        Write-SniperClipLog ("Configuration importée depuis "+$source)
        $script:restartRequested=$true
        $script:skipFinalSave=$true
        [System.Windows.Forms.MessageBox]::Show($form,(T "Configuration importée. SniperClip va redémarrer."),"SniperClip",[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Information)|Out-Null
        $script:allowRealClose=$true
        $form.Close()
    } catch {
        try{if($null -ne $zipSource){Remove-Item -LiteralPath $zipSource -Force -ErrorAction SilentlyContinue}}catch{}
        try{Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}catch{}
        [System.Windows.Forms.MessageBox]::Show($form,((T "Impossible d’importer la configuration :")+" `r`n"+$_.Exception.Message),(T "Import SniperClip"),[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Error)|Out-Null
        Write-SniperClipLog (("Import impossible : "+$_.Exception.Message)) "ERROR"
    }
}
function Open-SniperClipLog {
    try { if(Test-Path $script:LogFile){ Start-Process notepad.exe -ArgumentList @($script:LogFile) } } catch {}
}

