# Zone de notification (systray)
# La fenêtre est masquée/affichée via l'API Win32 ShowWindow.
# On évite ainsi Hide()/Show() et les changements de WindowState qui
# perturbent ShowDialog() et empêchent parfois la restauration depuis le systray.
$script:allowRealClose = $false
$script:trayIcon = $null
$script:trayMenu = $null

try {
    $trayMenu = New-Object System.Windows.Forms.ContextMenuStrip
    $trayMenu.ShowImageMargin = $false
    # Afficher explicitement la colonne de coche pour les options CheckOnClick.
    $trayMenu.ShowCheckMargin = $true

    $trayOpen = $trayMenu.Items.Add("Ouvrir SniperClip")
    $trayHide = $trayMenu.Items.Add("Masquer SniperClip")
    [void]$trayMenu.Items.Add("-")
    $trayStartup = $trayMenu.Items.Add((T "Démarrer SniperClip avec Windows"))
    $trayStartup.CheckOnClick = $true
    $trayStartup.Checked = Get-StartupEnabled
    $trayStartup.AutoSize = $true
    [void]$trayMenu.Items.Add("-")
    $trayLanguage = $trayMenu.Items.Add((T "Langue"))
    $langMenu = New-Object System.Windows.Forms.ToolStripDropDownMenu
    $langFr = $langMenu.Items.Add("Français")
    $langEn = $langMenu.Items.Add("English")
    $langEs = $langMenu.Items.Add("Español")
    $langDe = $langMenu.Items.Add("Deutsch")
    $langPl = $langMenu.Items.Add("Polski")
    $langJa = $langMenu.Items.Add("日本語")
    $langIt = $langMenu.Items.Add("Italiano")
    $trayLanguage.DropDown = $langMenu
    foreach($li in @($langFr,$langEn,$langEs,$langDe,$langPl,$langJa,$langIt)){ $li.CheckOnClick = $true }
    $langFr.Checked = ($script:Language -eq "fr"); $langEn.Checked = ($script:Language -eq "en"); $langEs.Checked = ($script:Language -eq "es"); $langDe.Checked = ($script:Language -eq "de"); $langPl.Checked = ($script:Language -eq "pl"); $langJa.Checked = ($script:Language -eq "ja"); $langIt.Checked = ($script:Language -eq "it")
    [void]$trayMenu.Items.Add("-")
    $trayExport = $trayMenu.Items.Add((T "Exporter la configuration"))
    $trayImport = $trayMenu.Items.Add((T "Importer une configuration"))
    $trayLog = $trayMenu.Items.Add((T "Ouvrir le journal"))
    [void]$trayMenu.Items.Add("-")
    $trayAbout = $trayMenu.Items.Add("About SniperClip")
    [void]$trayMenu.Items.Add("-")
    $trayQuit = $trayMenu.Items.Add((T "Quitter SniperClip"))

    $trayIcon = New-Object System.Windows.Forms.NotifyIcon
    $trayIcon.Text = "SniperClip"
    $trayIcon.ContextMenuStrip = $trayMenu
    $trayIcon.Visible = $true

    # Utiliser le logo officiel SniperClip dans le Systray.
    if($null -ne $script:appIcon){
        $trayIcon.Icon = $script:appIcon
    } else {
        # Secours si le fichier ICO est absent.
        $bmp = New-Object System.Drawing.Bitmap 32,32
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        try {
            $g.Clear([System.Drawing.Color]::White)
            $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::Black,2)
            $g.DrawRectangle($pen,3,3,26,26)
            $g.DrawLine($pen,3,13,29,13)
            $g.DrawLine($pen,3,22,29,22)
            $g.DrawLine($pen,12,3,12,29)
            $g.DrawLine($pen,21,3,21,29)
            $pen.Dispose()
        } finally { $g.Dispose() }
        $trayIcon.Icon = [System.Drawing.Icon]::FromHandle($bmp.GetHicon())
        $bmp.Dispose()
    }

    $showSniperClip = {
        Hide-Preview
        if(-not $form.IsHandleCreated){ $form.CreateControl() }
        [SniperClipNativeWindow]::ShowWindow($form.Handle,1) | Out-Null
        [SniperClipNativeWindow]::SetForegroundWindow($form.Handle) | Out-Null
    }
    $hideSniperClip = {
        Hide-Preview
        if($form.IsHandleCreated){ [SniperClipNativeWindow]::ShowWindow($form.Handle,0) | Out-Null }
    }

    $applyLanguage = {
        $trayOpen.Text=(T "Ouvrir SniperClip"); $trayHide.Text=(T "Masquer SniperClip")
        $trayStartup.Text=(T "Démarrer SniperClip avec Windows"); $trayLanguage.Text=(T "Langue")
        $trayQuit.Text=(T "Quitter SniperClip"); $trayExport.Text=(T "Exporter la configuration"); $trayImport.Text=(T "Importer une configuration"); $trayLog.Text=(T "Ouvrir le journal")
        $langFr.Text="Français"; $langEn.Text="English"; $langEs.Text="Español"; $langDe.Text="Deutsch"; $langPl.Text="Polski"; $langJa.Text="日本語"; $langIt.Text="Italiano"
        $langFr.Checked=($script:Language -eq "fr"); $langEn.Checked=($script:Language -eq "en"); $langEs.Checked=($script:Language -eq "es"); $langDe.Checked=($script:Language -eq "de"); $langPl.Checked=($script:Language -eq "pl"); $langJa.Checked=($script:Language -eq "ja"); $langIt.Checked=($script:Language -eq "it")
        # Actualise immédiatement l'interface principale lorsque la langue change.
        if($null -ne $title){ $title.Text="SniperClip" }
        if($null -ne $customButton){ $customButton.Text=(T "Personnaliser") }
        if($null -ne $resetSizeButton){ $resetSizeButton.Text=(T "Tailles par défaut") }
        if($null -ne $sizeButton){ $sizeButton.Text=(T "Taille des cellules") }
        if($null -ne $form){ Update-HeaderLayout }
        if($null -ne $menuCopy){ $menuCopy.Text=(T "Copier") }
        if($null -ne $menuEdit){ $menuEdit.Text=(T "Modifier la cellule") }
        if($null -ne $menuClear){ $menuClear.Text=(T "Effacer le contenu") }
        if($null -ne $menuShortcut){ $menuShortcut.Text=(T "Raccourci clavier…") }
        if($null -ne $menuSize){ $menuSize.Text=(T "Taille de la cellule") }
        if($null -ne $help){
            Update-HeaderLayout
        }
        if($null -ne $trayIcon){ $trayIcon.Text="SniperClip" }
    }
    $setLanguage = { param([string]$newLang)
        if($newLang -notin @("fr","en","es","de","pl","ja","it")){ return }
        $script:Language=$newLang
        try { Save-Slots } catch {}
        & $applyLanguage
    }
    $langFr.Add_Click({ & $setLanguage "fr" })
    $langEn.Add_Click({ & $setLanguage "en" })
    $langEs.Add_Click({ & $setLanguage "es" })
    $langDe.Add_Click({ & $setLanguage "de" })
    $langPl.Add_Click({ & $setLanguage "pl" })
    $langJa.Add_Click({ & $setLanguage "ja" })
    $langIt.Add_Click({ & $setLanguage "it" })
    # Applique immédiatement la langue mémorisée au démarrage, notamment aux
    # deux premières entrées du menu systray qui étaient initialisées en français.
    & $applyLanguage
    $trayOpen.Add_Click($showSniperClip)
    $trayHide.Add_Click($hideSniperClip)
    $trayStartup.Add_Click({
        $wanted = [bool]$trayStartup.Checked
        if(-not (Set-StartupEnabled $wanted)){
            $trayStartup.Checked = -not $wanted
        }
    })
    $trayExport.Add_Click({ Export-Configuration })
    $trayImport.Add_Click({ Import-Configuration })
    $trayLog.Add_Click({ Open-SniperClipLog })
    $trayAbout.Add_Click({ Show-AboutSniperClip })
    $trayQuit.Add_Click({
        $script:allowRealClose = $true
        $form.Close()
    })
    $trayIcon.Add_DoubleClick($showSniperClip)
    $form.Opacity=1.0
    $form.Add_Shown({
        if($null -ne $trayIcon){ $trayIcon.Visible=$true }
    })
    $trayIcon.Add_MouseClick({
        if($_.Button -eq [System.Windows.Forms.MouseButtons]::Left){
            & $showSniperClip
        }
    })
} catch {
    # Le systray ne doit jamais empêcher SniperClip de démarrer.
    if($null -ne $trayIcon){ try{$trayIcon.Dispose()}catch{} }
    $trayIcon=$null
    if($null -ne $trayMenu){ try{$trayMenu.Dispose()}catch{} }
    $trayMenu=$null
}

$form.Add_FormClosing({
    # Un clic sur X masque la fenêtre : il ne ferme pas SniperClip.
    if(-not $script:allowRealClose){
        $_.Cancel = $true
        Hide-Preview
        if($form.IsHandleCreated){ [SniperClipNativeWindow]::ShowWindow($form.Handle,0) | Out-Null }
        return
    }

    # Quitter SniperClip : dernière sauvegarde puis nettoyage complet.
    if($null -ne $configMoveTimer){ $configMoveTimer.Stop() }
    if($null -ne $resizeTimer){ $resizeTimer.Stop() }
    if(-not $script:skipFinalSave){ Save-Slots }
    Hide-Preview
    Unregister-CellHotkeys
    if($null -ne $shortcutTimer){
        $shortcutTimer.Stop()
        $shortcutTimer.Dispose()
    }
    if($null -ne $keyHook){
        $keyHook.Dispose()
    }
})

$form.Add_FormClosed({
    Write-SniperClipLog "Fermeture de SniperClip."
    if($null -ne $trayIcon){
        try { $trayIcon.Visible=$false } catch {}
        try { $trayIcon.Dispose() } catch {}
        $script:trayIcon=$null
    }
    if($null -ne $trayMenu){
        try { $trayMenu.Dispose() } catch {}
        $script:trayMenu=$null
    }
})

# Raccourcis clavier globaux
# Le hook clavier tourne dans le callback natif Windows. Pour eviter d'appeler
# directement PowerShell depuis ce callback (ce qui n'est pas sur), V4.4
# place les touches dans une file thread-safe. Un Timer WinForms, execute sur
# le thread UI, lit ensuite cette file et declenche la copie.
Add-Type @"
using System;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Collections.Concurrent;

public class SniperClipKeyboardHook {
    private const int WH_KEYBOARD_LL = 13;
    private const int WM_KEYDOWN = 0x0100;
    private const int WM_SYSKEYDOWN = 0x0104;
    private const int MOD_ALT = 0x0001;
    private const int MOD_CONTROL = 0x0002;
    private const int MOD_SHIFT = 0x0004;
    private const int MOD_WIN = 0x0008;

    private delegate IntPtr LowLevelKeyboardProc(int nCode, IntPtr wParam, IntPtr lParam);
    private LowLevelKeyboardProc _proc;
    private IntPtr _hook = IntPtr.Zero;

    private ConcurrentQueue<long> _queue = new ConcurrentQueue<long>();

    public SniperClipKeyboardHook() {
        _proc = HookCallback;
        using(Process p=Process.GetCurrentProcess())
        using(ProcessModule m=p.MainModule) {
            _hook = SetWindowsHookEx(WH_KEYBOARD_LL, _proc,
                GetModuleHandle(m.ModuleName), 0);
        }
        if(_hook == IntPtr.Zero)
            throw new Exception("Impossible d'installer le hook clavier global.");
    }

    public bool TryDequeue(out long value) {
        return _queue.TryDequeue(out value);
    }

    public int QueueCount {
        get { return _queue.Count; }
    }

    public void Dispose() {
        if(_hook != IntPtr.Zero) {
            UnhookWindowsHookEx(_hook);
            _hook=IntPtr.Zero;
        }
        GC.KeepAlive(_proc);
    }

    private IntPtr HookCallback(int nCode, IntPtr wParam, IntPtr lParam) {
        if(nCode >= 0 && (wParam.ToInt32()==WM_KEYDOWN || wParam.ToInt32()==WM_SYSKEYDOWN)) {
            int vk=Marshal.ReadInt32(lParam);
            int mods=0;

            if((GetAsyncKeyState(0x11) & 0x8000)!=0) mods |= MOD_CONTROL;
            if((GetAsyncKeyState(0x12) & 0x8000)!=0) mods |= MOD_ALT;
            if((GetAsyncKeyState(0x10) & 0x8000)!=0) mods |= MOD_SHIFT;
            if((GetAsyncKeyState(0x5B) & 0x8000)!=0 || (GetAsyncKeyState(0x5C) & 0x8000)!=0) mods |= MOD_WIN;

            long packed=((long)mods << 32) | ((long)(uint)vk);
            _queue.Enqueue(packed);
        }
        return CallNextHookEx(_hook,nCode,wParam,lParam);
    }

    [DllImport("user32.dll", CharSet=CharSet.Auto, SetLastError=true)]
    private static extern IntPtr SetWindowsHookEx(int idHook, LowLevelKeyboardProc lpfn,
        IntPtr hMod, uint dwThreadId);

    [DllImport("user32.dll", CharSet=CharSet.Auto, SetLastError=true)]
    private static extern bool UnhookWindowsHookEx(IntPtr hhk);

    [DllImport("user32.dll", CharSet=CharSet.Auto)]
    private static extern IntPtr CallNextHookEx(IntPtr hhk,int nCode,IntPtr wParam,IntPtr lParam);

    [DllImport("kernel32.dll", CharSet=CharSet.Auto)]
    private static extern IntPtr GetModuleHandle(string lpModuleName);

    [DllImport("user32.dll")]
    private static extern short GetAsyncKeyState(int vKey);
}
"@

$keyHook=New-Object SniperClipKeyboardHook

$shortcutTimer=New-Object System.Windows.Forms.Timer
$shortcutTimer.Interval=25
$shortcutTimer.Add_Tick({
    while($keyHook.QueueCount -gt 0){
        [long]$packed=0
        if(-not $keyHook.TryDequeue([ref]$packed)){ break }

        # Le paquet contient deux valeurs sur 16 bits :
        # bits 0-15  = VirtualKey
        # bits 32-47 = modificateurs.
        # Ne surtout pas utiliser 0xFFFFFFFF ici : PowerShell peut traiter
        # cette constante comme une valeur Int64 non convertible en Int32.
        $vk=[int]($packed -band 0xFFFF)
        $mods=[int](($packed -shr 32) -band 0xFFFF)

        if($vk -le 0 -or $vk -gt 255){ continue }

        # Ctrl+Alt+V : afficher/masquer SniperClip
        if($vk -eq 0x56 -and (($mods -band 0x0003) -eq 0x0003)){
            if($form.Opacity -gt 0){
                & $hideSniperClip
            }else{
                & $showSniperClip
            }
            continue
        }

        # Raccourcis des cellules
        for($i=0;$i -lt $count;$i++){
            $slot=$slots[$i]
            if([int]$slot.ShortcutKey -eq $vk -and [int]$slot.ShortcutModifiers -eq $mods){
                Hide-Preview
                if(-not [string]::IsNullOrEmpty($slot.Text) -or -not [string]::IsNullOrEmpty($slot.Rtf)){
                    Set-ClipboardFromSlot $i
                }
                break
            }
        }
    }
})
$shortcutTimer.Start()

if($null -eq $form){
    throw "La fenetre principale SniperClip n'a pas pu etre creee."
}
Register-CellHotkeys

# Dernière restauration de la fenêtre, après la création de tous les contrôles.
# Cela évite qu'un événement Resize/Move de l'initialisation ne remplace les
# valeurs sauvegardées par la position/tailles par défaut.
if($null -ne $savedConfig -and $null -ne $savedConfig.Window){
    try{
        $sw=[int]$savedConfig.Window.Width
        $sh=[int]$savedConfig.Window.Height
        $sx=[int]$savedConfig.Window.Left
        $sy=[int]$savedConfig.Window.Top

        $form.WindowState=[System.Windows.Forms.FormWindowState]::Normal
        $form.StartPosition="Manual"

        if($sw -ge 520 -and $sh -ge 300){
            $savedRect=New-Object System.Drawing.Rectangle($sx,$sy,$sw,$sh)
            $visible=$false
            foreach($screen in [System.Windows.Forms.Screen]::AllScreens){
                if($screen.WorkingArea.IntersectsWith($savedRect)){
                    $visible=$true
                    break
                }
            }

            if(-not $visible){
                $screen=[System.Windows.Forms.Screen]::PrimaryScreen
                $wa=$screen.WorkingArea
                $sx=$wa.Left + [math]::Max(0,[int](($wa.Width-$sw)/2))
                $sy=$wa.Top + [math]::Max(0,[int](($wa.Height-$sh)/2))
            }

            $form.Bounds=New-Object System.Drawing.Rectangle($sx,$sy,$sw,$sh)
        }

        if($null -ne $savedConfig.Window.State){
            try{
                $savedState=[System.Windows.Forms.FormWindowState]$savedConfig.Window.State
                if($savedState -ne [System.Windows.Forms.FormWindowState]::Minimized){
                    $form.WindowState=$savedState
                }
            }catch{}
        }
    }catch{}
}

Apply-Theme

$script:isInitializing = $false

# Boucle de messages WinForms non modale : indispensable pour que le systray puisse
# masquer/réafficher la fenêtre sans que ShowDialog() ne termine la boucle lorsqu'elle est cachée.
[System.Windows.Forms.Application]::Run($form)
# Fermeture explicite du processus PowerShell après la fermeture réelle de la fenêtre.
# La sauvegarde a déjà été effectuée dans FormClosing.
if($script:db -ne [IntPtr]::Zero){ try{ [SniperClipSQLite]::sqlite3_close($script:db) | Out-Null }catch{}; $script:db=[IntPtr]::Zero }
try { $form.Dispose() } catch {}
# Le mutex doit être libéré AVANT de relancer le VBS : sinon le nouveau
# processus se voit encore comme une seconde instance et quitte immédiatement.
try { $script:singleInstanceMutex.ReleaseMutex() } catch {}
try { $script:singleInstanceMutex.Dispose() } catch {}
if($script:restartRequested){
    try {
        $vbs=Join-Path $PSScriptRoot "Lancer SniperClip.vbs"
        if(Test-Path -LiteralPath $vbs){
            # Le chemin peut contenir des espaces (OneDrive, etc.).
            # On lance wscript de façon détachée, après avoir libéré le mutex.
            $wscript=Join-Path $env:WINDIR "System32\wscript.exe"
            $quotedVbs='"'+$vbs.Replace('"','\"')+'"'
            Start-Process -FilePath $wscript -ArgumentList @('//B','//NoLogo',$quotedVbs) -WindowStyle Hidden -WorkingDirectory $PSScriptRoot | Out-Null
        }
    } catch { Write-SniperClipLog ("Redémarrage automatique impossible : "+$_.Exception.Message) "ERROR" }
}
[System.Environment]::Exit(0)

